import React, { useState } from 'react';

export default function Simulador({ fluxo }) {
  const [historico, setHistorico] = useState([]);
  const [etapaAtual, setEtapaAtual] = useState(0);

  const etapa = fluxo?.[etapaAtual];

  const handleOpcao = (opcao) => {
    const novaMensagemUsuario = { tipo: 'usuario', texto: opcao.texto };
    const novaMensagemBot = { tipo: 'bot', texto: opcao.mensagem || '...' };

    setHistorico(prev => [...prev, novaMensagemUsuario, novaMensagemBot]);

    if (opcao.acao === 'submenu') {
      // Reinicia o submenu como novo fluxo interno
      setHistorico(prev => [...prev, { tipo: 'sistema', texto: '(Entrando no submenu...)' }]);
      setEtapaAtual(-1); // Simulação básica: submenu não implementado ainda
    } else {
      setEtapaAtual(prev => prev + 1); // Vai para próxima etapa
    }
  };

  return (
    <div className="bg-white border border-gray-300 rounded-lg p-4 max-w-md mx-auto mt-6 shadow">
      <h2 className="text-lg font-semibold mb-4">🧪 Simulador de Conversa</h2>

      <div className="space-y-2 mb-4 max-h-96 overflow-y-auto">
        {historico.map((msg, index) => (
          <div
            key={index}
            className={`p-2 rounded text-sm w-fit ${msg.tipo === 'usuario' ? 'bg-blue-100 self-end ml-auto' : 'bg-gray-100'}`}
          >
            {msg.texto}
          </div>
        ))}

        {etapa && (
          <>
            <div className="p-2 bg-gray-100 rounded text-sm">{etapa.mensagem}</div>

            {etapa.opcoes?.map((opcao, idx) => (
              <button
                key={idx}
                className="mt-2 block w-full text-left bg-blue-600 text-white px-3 py-1 rounded text-sm"
                onClick={() => handleOpcao(opcao)}
              >
                {opcao.texto || '(opção sem texto)'}
              </button>
            ))}
          </>
        )}
      </div>

      {!etapa && (
        <p className="text-gray-500 text-sm italic text-center">Fim da simulação.</p>
      )}
    </div>
  );
}
